package main

import (
	"log"
	"net/http"
	_ "net/http/pprof" // registers /debug/pprof on http.DefaultServeMux
)

func main() {
	http.HandleFunc("/healthz", health)
	http.HandleFunc("/v1/quote", quoteHandler)

	// One listener for everything: LB traffic, health checks, and —
	// handy during incidents — the pprof endpoints.
	log.Fatal(http.ListenAndServe(":8080", nil))
}

// Incident runbook (team wiki):
//  - memory growth: curl :8080/debug/pprof/heap and read the top of
//    alloc_space — the biggest cumulative allocator is the leak;
//  - latency: if the 30s CPU profile looks empty, the box is healthy,
//    go look at the database instead.
